function renderFatalError(e){const raw=String(e?.code||''),code=/^\d{3}$/.test(raw)?raw:'ERROR',titles={400:'Bad request',401:'Authorization required',403:'Access denied',404:'Resource not found',408:'Request timed out',413:'Response too large',415:'Unsupported media type',429:'Too many requests',500:'Server error',502:'Upstream error',503:'Service unavailable',504:'Gateway timeout',CONFIG:'Configuration error',ERROR:'Database unavailable'},title=titles[raw]||titles.ERROR,msg=esc(e?.message||'The database could not be loaded.');$('#contentView').classList.add('active');$('#detailView').classList.remove('active');$('#viewEyebrow').textContent=code;$('#viewTitle').textContent=title;$('#viewDescription').textContent='VulkanScope Database could not complete this request.';$('#filters').hidden=true;$('#content').innerHTML=`<section class="error-panel"><div class="error-orb" aria-hidden="true">!</div><div><h3>${esc(title)}</h3><p>${msg}</p><div class="error-actions"><a class="error-action primary" href="./">Reports</a><a class="error-action" href="https://github.com/EFIShell0/VulkanScope" target="_blank" rel="noopener noreferrer">VulkanScope on GitHub</a><button class="error-action" id="retryLoad" type="button">Try again</button></div></div></section>`;$('#retryLoad').onclick=()=>location.reload()}
let searchTimer=0;$('#globalSearch').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{resetReportPage();render()},90)};for(const id of FILTER_IDS){const el=$(`#${id}`);if(!el)continue;if(id==='displayOrderFilter'){el.onchange=()=>{if(state.view==='display')render();return};continue}el.onchange=()=>{resetReportPage();render()}};$('#detailBack').onclick=()=>{state.detailId=null;syncDocumentTitle();syncRouteUrl(true);render()};$('#navScrollLeft').onclick=()=>scrollMainNav(-1);$('#navScrollRight').onclick=()=>scrollMainNav(1);$('#mainNav').addEventListener('scroll',syncNavScrollUi,{passive:true});$('#mainNav').addEventListener('wheel',e=>{const n=$('#mainNav');if(n.scrollWidth<=n.clientWidth)return;if(Math.abs(e.deltaY)>Math.abs(e.deltaX)){e.preventDefault();n.scrollLeft+=e.deltaY}else if(e.deltaX)n.scrollLeft+=e.deltaX},{passive:false});window.addEventListener('resize',syncNavScrollUi,{passive:true});window.addEventListener('hashchange',handleRouteEvent);window.addEventListener('popstate',handleRouteEvent);enhanceSelects();load().catch(e=>{$('#metrics').innerHTML='';nav();renderFatalError(e)});
